import{_ as o,l as i,o as e,c as n,v as r,p as s,x as t,d,i as E,S as h}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"选择投影连接的顺序","description":"","frontmatter":{"title":"选择投影连接的顺序","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/algebra-reorder.md","filePath":"cs/algebra-reorder.md","lastUpdated":1789023840000}'),p={name:"cs/algebra-reorder.md"};function c(_,a,m,B,u,f){const l=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="选择投影连接的顺序" tabindex="-1">选择投影连接的顺序 <a class="header-anchor" href="#选择投影连接的顺序" aria-label="Permalink to &quot;选择投影连接的顺序&quot;">​</a></h1><div class="epigraph"><p>同一表达式可以先选后连或先连后选；等价变换不改结果关系，只改中间结果有多大。</p><footer>—— 据 Codd 1972 代数；Ullman 对代数等价；Ramakrishnan and Gehrke</footer></div><p><a href="/cs/relational-algebra">上一课</a>给出选择、投影、连接等闭运算。本课不重推五种基本运算。缺口是：代数树的形状。先把两个大关系连接再选择，与先选择再连接，若谓词只涉及一侧，结果相同，页 I/O 差几个数量级。后课 SQL 优化器吃的就是这些律。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>代数是指称，不是执行计划。但课序马上要进声明语言与物理算子，必须先承认：<strong>连接结合律、选择下推、投影可穿连接</strong>（在无副作用、集合语义下）。缺口不是代价数字，而是「合法重排」这一层。NULL 与包语义会打破部分律，后课再钉。</p><p><span class="marginnote">选择下推：σ 可以穿过一侧无该属性的连接，落到含该属性的叶子。投影要保留连接键，否则不能穿。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写同一查询的两棵树：σ–⋈ 与 ⋈–σ。用集合恒等说明它们相等。结合律让三点连接改括号。本课不算页数，只要求读者看到中间基数会变。物理算法下一单元才出现。</p>',8)),(e(),s(h,null,{default:t(()=>[E(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%90%8C%E4%B8%80%E4%BB%A3%E6%95%B0%E8%A1%A8%E8%BE%BE%E5%BC%8F%22%5D%20--%3E%20T1%5B%22%E5%85%88%E8%BF%9E%E6%8E%A5%E5%90%8E%E9%80%89%E6%8B%A9%22%5D%0A%20%20Q%20--%3E%20T2%5B%22%E5%85%88%E9%80%89%E6%8B%A9%E5%90%8E%E8%BF%9E%E6%8E%A5%22%5D%0A%20%20T1%20--%3E%20EQ%5B%22%E5%90%8C%E4%B8%80%E7%BB%93%E6%9E%9C%E5%85%B3%E7%B3%BB%22%5D%0A%20%20T2%20--%3E%20EQ%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>重排把「查询含义」与「操作顺序」分开，这是数据独立性在运算层的投影。后课代价估计给每棵物理树打分；没有本课的等价意识，优化器会被看成随便改用户 SQL。外键约束有时提供额外等价（存在性），本课不展开。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入外连接的全部非等价例子当主干，不把分布式下推到存储引擎的接口写完。如何用英文句子写查询，下一课 SQL 声明性。</p><p>后课默认：选择、投影、连接可以按律改序。语言层还没有。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>代数律允许改树而不改结果。</li><li>中间大小可变，代价是后课的事。</li><li>SQL 下一课。</li><li>出处：Codd 1972；Ullman；Ramakrishnan and Gehrke。</li></ul>',7))])}const A=o(p,[["render",c]]);export{b as __pageData,A as default};
